const NOT_FOUND = -1;

// CONTRACT for flattenPlaylist(nestedPlaylist, flatSongIds):
//     when this call returns, every song id inside `nestedPlaylist` —
//     including songs buried in folders within folders — has been
//     appended to `flatSongIds`, in exact play order.
const flattenPlaylist = (nestedPlaylist, flatSongIds) => {
    for (const element of nestedPlaylist) {
        // Base case: a plain integer is a song, so record it in play order.
        if (typeof element === 'number') {
            flatSongIds.push(element);
            continue;
        }

        // Recurse on neighbors: an array is a folder, so dive inside it
        // the moment we reach it (this matches the play order).
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, every song inside this
        // folder has been appended to `flatSongIds` in play order. Trust
        // it, do not trace it. Songs recorded directly here + each
        // folder's guaranteed songs, all in the order we meet them —
        // exactly this function's contract, kept.
        flattenPlaylist(element, flatSongIds);
    }
};

const kthSong = (playlist, k) => {
    const flatSongIds = [];

    // The recursive leap of faith: trust the contract. When this
    // call returns, `flatSongIds` holds every song in the whole
    // playlist in play order. We do not trace inside; we just read
    // off the k-th entry.
    flattenPlaylist(playlist, flatSongIds);

    // Empty folders contribute nothing, so the playlist can hold
    // fewer than k songs.
    if (k > flatSongIds.length) return NOT_FOUND;

    // k is 1-indexed, so the k-th song lives at index k - 1.
    return flatSongIds[k - 1];
};

const buildChildrenGraph = (ids, feeds) => {
    const childrenGraph = {};

    for (let index = 0; index < ids.length; index++) {
        const sprinklerId = ids[index];
        const feederId = feeds[index];

        const feederInGraph = childrenGraph.hasOwnProperty(feederId);
        if (!feederInGraph) childrenGraph[feederId] = [];

        childrenGraph[feederId].push(sprinklerId);
    }

    return childrenGraph;
};

// CONTRACT for sumSubtreeLiters(childrenGraph, litersById, sprinklerId):
//     when this call returns, the returned value equals the liters
//     used by `sprinklerId` plus the liters used by every sprinkler
//     fed through it, all the way down.
const sumSubtreeLiters = (childrenGraph, litersById, sprinklerId) => {
    // Base case is automatic: a sprinkler that feeds no other
    // sprinklers has no children to recurse on.

    // Process node
    let totalLiters = litersById[sprinklerId];

    // Recurse on neighbors
    const sprinklerInGraph = childrenGraph.hasOwnProperty(sprinklerId);
    if (!sprinklerInGraph) return totalLiters;

    const childIds = childrenGraph[sprinklerId];
    for (const childId of childIds) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, it hands back the total
        // liters for `childId` and everything fed through it. Trust it,
        // do not trace it. This sprinkler's own liters + each child's
        // guaranteed total = exactly this function's contract.
        totalLiters += sumSubtreeLiters(childrenGraph, litersById, childId);
    }

    return totalLiters;
};

const litersSaved = (ids, feeds, liters, shutId) => {
    // The piping is a tree, so shutting one sprinkler cuts off exactly
    // the subtree rooted at it.
    const childrenGraph = buildChildrenGraph(ids, feeds);

    const litersById = {};
    for (let index = 0; index < ids.length; index++) {
        litersById[ids[index]] = liters[index];
    }

    // The recursive leap of faith: trust the contract. When this
    // call returns, its value is the total liters used by `shutId`
    // and every sprinkler fed through it. We do not trace inside; we
    // just return that total.
    return sumSubtreeLiters(childrenGraph, litersById, shutId);
};

const BASE_CAMP = 0;

// CONTRACT for countRoutesFromCamp(graph, curCamp, summitCamp):
//     when this call returns, the returned value equals the number of
//     different trail routes that lead from `curCamp` all the way to
//     `summitCamp`.
const countRoutesFromCamp = (graph, curCamp, summitCamp) => {
    // Base case: reaching the summit completes exactly one route.
    if (curCamp === summitCamp) return 1;

    // Process node
    let routeCount = 0;

    // Recurse on neighbors
    const neighborCamps = graph[curCamp];
    for (const neighborCamp of neighborCamps) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, it hands back the number
        // of routes from `neighborCamp` to the summit. Trust it, do not
        // trace it. Every route out of `curCamp` starts by stepping to
        // some neighbor, so adding up each neighbor's guaranteed count
        // gives exactly this function's contract.
        routeCount += countRoutesFromCamp(graph, neighborCamp, summitCamp);
    }

    return routeCount;
};

const countSummitRoutes = (graph) => {
    const summitCamp = graph.length - 1;

    // Every trail leads uphill, so the graph has no cycles and we
    // never need a visited set.
    // The recursive leap of faith: trust the contract. When this
    // call returns, its value is the number of routes from base camp
    // to the summit. We do not trace inside; we just return it.
    return countRoutesFromCamp(graph, BASE_CAMP, summitCamp);
};

const buildWeightedGraph = (roads) => {
    const graph = {};

    for (const road of roads) {
        const [warehouseOne, warehouseTwo, hours] = road;

        const warehouseOneInGraph = graph.hasOwnProperty(warehouseOne);
        const warehouseTwoInGraph = graph.hasOwnProperty(warehouseTwo);

        if (!warehouseOneInGraph) graph[warehouseOne] = [];
        if (!warehouseTwoInGraph) graph[warehouseTwo] = [];

        // Roads are two-way, so add each road in both directions.
        graph[warehouseOne].push([warehouseTwo, hours]);
        graph[warehouseTwo].push([warehouseOne, hours]);
    }

    return graph;
};

// CONTRACT for recordArrivalHours(graph, warehouse, hoursSoFar, bestKnownHours):
//     when this call returns, `bestKnownHours` has an entry for
//     `warehouse` and for every warehouse reachable from it, holding
//     the fewest driving hours needed to arrive there.
const recordArrivalHours = (graph, warehouse, hoursSoFar, bestKnownHours) => {
    // Base case: if we already reached this warehouse at least as fast,
    // this route cannot improve anything (this also stops us from
    // driving back and forth forever).
    const warehouseHasBestTime = bestKnownHours.hasOwnProperty(warehouse);
    if (warehouseHasBestTime && bestKnownHours[warehouse] <= hoursSoFar) return;

    // Process node
    bestKnownHours[warehouse] = hoursSoFar;

    // Recurse on neighbors
    const warehouseInGraph = graph.hasOwnProperty(warehouse);
    if (!warehouseInGraph) return;

    const neighborRoads = graph[warehouse];
    for (const neighborRoad of neighborRoads) {
        const [neighborWarehouse, roadHours] = neighborRoad;

        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, `bestKnownHours` has the
        // fewest hours for `neighborWarehouse` and everything reachable
        // beyond it. Trust it, do not trace it. This function already
        // recorded `warehouse`'s time, and each neighbor's contract covers
        // the warehouses past it — together, that is this function's full
        // contract, kept.
        recordArrivalHours(
            graph,
            neighborWarehouse,
            hoursSoFar + roadHours,
            bestKnownHours,
        );
    }
};

const deliveryHours = (n, roads, hq, target) => {
    const graph = buildWeightedGraph(roads);

    // Track the best-known driving time from hq to every warehouse,
    // then read off the answer for the target. The roads form a tree,
    // so the one route the DFS finds is THE route.
    const bestKnownHours = {};
    // The recursive leap of faith: trust the contract. When this
    // call returns, `bestKnownHours` holds the driving time from `hq`
    // to every reachable warehouse. We do not trace inside; we just
    // read off the entry for `target`.
    recordArrivalHours(graph, hq, 0, bestKnownHours);

    return bestKnownHours[target];
};

const ROOT_BULB = 0;

const buildGraph = (edges) => {
    const graph = {};

    for (const edge of edges) {
        const [nodeOne, nodeTwo] = edge;

        const nodeOneInGraph = graph.hasOwnProperty(nodeOne);
        const nodeTwoInGraph = graph.hasOwnProperty(nodeTwo);

        if (!nodeOneInGraph) graph[nodeOne] = [];
        if (!nodeTwoInGraph) graph[nodeTwo] = [];

        graph[nodeOne].push(nodeTwo);
        graph[nodeTwo].push(nodeOne);
    }

    return graph;
};

// CONTRACT for countGoldFromBulb(graph, bulb, isGold, visited):
//     when this call returns, `bulb` and every bulb reachable from it
//     is in the visited set, and the returned value is how many of
//     the bulbs this call put into visited are gold (with `bulb`
//     itself being gold exactly when `isGold` is true).
const countGoldFromBulb = (graph, bulb, isGold, visited) => {
    // Base case
    if (visited.has(bulb)) return 0;

    // Process node
    visited.add(bulb);

    // Neighbors must alternate colors, so a bulb's color depends only
    // on how many wires away from bulb 0 it is: even = gold, odd = silver.
    let goldCount = isGold ? 1 : 0;

    // Recurse on neighbors
    const bulbInGraph = graph.hasOwnProperty(bulb);
    if (!bulbInGraph) return goldCount;

    const neighbors = graph[bulb];
    for (const neighbor of neighbors) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, `neighbor` and everything
        // reachable from it is in visited, and it hands back the number
        // of gold bulbs it put there (the neighbor's color is the
        // opposite of ours). Trust it, do not trace it. This bulb's own
        // 1 or 0 + each neighbor call's guaranteed count = exactly this
        // function's contract.
        goldCount += countGoldFromBulb(graph, neighbor, !isGold, visited);
    }

    return goldCount;
};

const countGoldBulbs = (n, wires) => {
    const graph = buildGraph(wires);
    const visited = new Set();

    // The recursive leap of faith: trust the contract. When this
    // call returns, its value is the total number of gold bulbs in
    // the whole string of lights (bulb 0 is gold). We do not trace
    // inside; we just return that number.
    return countGoldFromBulb(graph, ROOT_BULB, true, visited);
};

const TOP_DEPTH = 1;

// CONTRACT for findShallowestItemDepth(items, curDepth):
//     when this call returns, the returned value equals the depth of
//     the shallowest integer anywhere inside `items`, where the
//     elements directly inside sit at depth `curDepth` (Infinity if
//     there are no integers at all).
const findShallowestItemDepth = (items, curDepth) => {
    let shallowestDepth = Infinity;

    for (const element of items) {
        // Base case: an integer sits at the current depth.
        if (typeof element === 'number') {
            shallowestDepth = Math.min(shallowestDepth, curDepth);
            continue;
        }

        // Recurse on neighbors: dive one box deeper.
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, it hands back the depth of
        // the shallowest integer inside this box. Trust it, do not trace
        // it. The shallowest of the integers seen right here and each
        // box's guaranteed answer = exactly this function's contract.
        const depthInsideBox = findShallowestItemDepth(element, curDepth + 1);
        shallowestDepth = Math.min(shallowestDepth, depthInsideBox);
    }

    return shallowestDepth;
};

// CONTRACT for sumItemsAtDepth(items, curDepth, targetDepth):
//     when this call returns, the returned value equals the sum of
//     every integer inside `items` that sits at exactly depth
//     `targetDepth`, where the elements directly inside sit at depth
//     `curDepth`.
const sumItemsAtDepth = (items, curDepth, targetDepth) => {
    let itemSum = 0;

    for (const element of items) {
        // Base case: an integer only counts if it sits at the target depth.
        if (typeof element === 'number') {
            if (curDepth === targetDepth) itemSum += element;
            continue;
        }

        // Recurse on neighbors
        // The recursive leap of faith, one level down: same contract —
        // this call hands back the sum of this box's integers at exactly
        // `targetDepth`. Trust it, do not trace it. Integers counted here
        // + each box's guaranteed sum = exactly this function's contract.
        itemSum += sumItemsAtDepth(element, curDepth + 1, targetDepth);
    }

    return itemSum;
};

const topLayerSum = (items) => {
    // Pass 1: discover the shallowest depth that holds any integer.
    // The recursive leap of faith: trust the contract. When this
    // call returns, `shallowestDepth` is the depth of the shallowest
    // integer in the whole pile. We do not trace inside; we just use
    // that depth as the target for pass 2.
    const shallowestDepth = findShallowestItemDepth(items, TOP_DEPTH);

    // Pass 2: sum only the integers sitting at that depth.
    // The recursive leap of faith again: when this call returns, its
    // value is the sum of every integer at that depth. We do not
    // trace inside; we just return it.
    return sumItemsAtDepth(items, TOP_DEPTH, shallowestDepth);
};

const GAS_POCKET = 'G';
const RUPTURED = 'X';
const SAFE = 'S';

const getPositionString = (row, col) => `${row}, ${col}`;
const directions = [
    [0, 1],
    [1, 0],
    [0, -1],
    [-1, 0],
];

const isInBounds = (grid, row, col) => {
    const numRows = grid.length;
    const numCols = grid[0].length;

    const rowInBounds = row >= 0 && row < numRows;
    const colInBounds = col >= 0 && col < numCols;

    return rowInBounds && colInBounds;
};

const countNeighborGasPockets = (cave, row, col) => {
    // Gas only seeps through the four flat walls, so only the
    // 4 orthogonal neighbors count (no diagonals!).
    let gasCount = 0;

    for (const direction of directions) {
        const [rowChange, colChange] = direction;

        const newRow = row + rowChange;
        const newCol = col + colChange;

        if (!isInBounds(cave, newRow, newCol)) continue;

        if (cave[newRow][newCol] === GAS_POCKET) gasCount++;
    }

    return gasCount;
};

// CONTRACT for revealCell(cave, row, col, visited):
//     when this call returns, (`row`, `col`) is revealed and in the
//     visited set, and if it touches no gas the reveal has spread:
//     every square reachable from it through gas-free squares is
//     revealed too. Squares off the board or already in visited are
//     left unchanged.
const revealCell = (cave, row, col, visited) => {
    // Base cases
    if (!isInBounds(cave, row, col)) return;

    const curPositionString = getPositionString(row, col);
    if (visited.has(curPositionString)) return;

    // Process node
    visited.add(curPositionString);

    const neighborGasCount = countNeighborGasPockets(cave, row, col);

    // A cell next to gas shows its danger count and stops the spread.
    if (neighborGasCount > 0) {
        cave[row][col] = String(neighborGasCount);
        return;
    }

    cave[row][col] = SAFE;

    // Recurse on neighbors
    for (const direction of directions) {
        const [rowChange, colChange] = direction;

        const newRow = row + rowChange;
        const newCol = col + colChange;

        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, the neighboring square
        // (and, if it is gas-free, everything reachable beyond it) is
        // revealed and in visited. Trust it, do not trace it. This
        // function already revealed (`row`, `col`); each direction's
        // contract reveals the rest of the safe area — together, that is
        // this function's full contract, kept.
        revealCell(cave, newRow, newCol, visited);
    }
};

const surveyCave = (cave, row, col) => {
    // Drilling straight into gas ruptures the pocket and nothing spreads.
    if (cave[row][col] === GAS_POCKET) {
        cave[row][col] = RUPTURED;
        return cave;
    }

    const visited = new Set();
    // The recursive leap of faith: trust the contract. When this
    // call returns, the drilled square and the whole safe area
    // connected to it are revealed, with danger counts on the edge.
    // We do not trace inside; we just return the updated cave.
    revealCell(cave, row, col, visited);

    return cave;
};

// CONTRACT for generateCodes(dials, dialIndex, codeSoFar, allCodes):
//     when this call returns, every valid full code that starts with
//     `codeSoFar` and continues with runes from dial `dialIndex`
//     onward has been appended to `allCodes`.
const generateCodes = (dials, dialIndex, codeSoFar, allCodes) => {
    // Base case
    if (dialIndex === dials.length) {
        allCodes.push(codeSoFar);
        return;
    }

    // Process node
    const previousRune = codeSoFar[codeSoFar.length - 1];

    // Traverse neighbors
    const runes = dials[dialIndex];

    for (const rune of runes) {
        // Two neighboring dials may never show the same rune, so skip
        // any rune that matches the dial to our left.
        if (rune === previousRune) continue;

        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, every valid code that
        // starts with `codeSoFar` plus `rune` has been appended to
        // `allCodes`. Trust it, do not trace it. Trying every allowed
        // rune on this dial, each with its guaranteed completions, covers
        // every valid code that starts with `codeSoFar` — exactly this
        // function's contract, kept.
        generateCodes(dials, dialIndex + 1, codeSoFar + rune, allCodes);
    }
};

const allRuneCodes = (dials) => {
    const allCodes = [];

    // The recursive leap of faith: trust the contract. When this
    // call returns, `allCodes` holds every valid code built from dial
    // 0 onward — the complete answer. We do not trace inside; we just
    // return the list.
    generateCodes(dials, 0, '', allCodes);

    return allCodes;
};
